-- Radiance Bomb / Gold token (English, Chinese), one acrylic token per champion for the China fan support event,
-- and the picture for the Chinese Radiance Booster Display. Safe to run more than once.
insert into promo_items (id, r, data)
select 'item-10869', 10869, $j${"cat": "PROMO", "nm": "Bomb / Gold (Radiance Token T02 / T05)", "se": "RAD", "cn": "T02 / T05", "ra": "Promo", "do": "N/A", "tg": "Token\nRadiance Vault", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/bomb-gold-t02-t05-radiance-token-en-item-10869.webp", "inf": "Double-sided full-art Radiance token (Bomb on one side, Gold on the other), T02 / T05, English. Comes in the Radiance Vault.", "r": 10869, "id": "item-10869", "la": "English", "ev": "Radiance Vault", "ty": "Token", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": ""}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10869' or (data->>'nm' = $n$Bomb / Gold (Radiance Token T02 / T05)$n$ and data->>'la' = 'English'));
